static int[] slideLeft(int[] row) {
        int n = row.length;
        int[] out = new int[n];
        int pos = 0;
        int prev = 0;
        for (int i = 0; i < n; i++) {
            int v = row[i];
            if (v == 0) {
                continue;
            }
            if (prev == v) {
                out[pos - 1] = 2 * v;
                prev = 0;
            } else {
                out[pos++] = v;
                prev = v;
            }
        }
        return out;
    }
```
